#pragma once

// Turns established format facts into readable Avid compression names. Readers
// keep their original properties and evidence; this helper does no reading and
// does not choose between a database and a media header.

#include "mediaduration.h"

#include <QByteArray>
#include <QPair>
#include <QString>
#include <optional>

namespace MediaEngine::Detail
{
	struct CompressionFacts
	{
		QByteArray codingLabel;
		QString descriptorClass;
		// The OMF/MDB caller validates the original property types and lengths.
		QByteArray legacyCompression;
		std::optional<qint64> legacyResolution;
		bool codingAbsent = false; // Established absence, not an unreadable label.
		QPair<qint64, qint64> geometry;
		MediaRate rate;
		std::optional<qint64> layout;
		std::optional<qint64> depth;
		std::optional<qint64> horizontal;
		std::optional<qint64> vertical;
		QString bitDepth;
		QString sampleFormat;
		// Supplied only after the reader establishes a sole alpha component.
		std::optional<qint64> alphaDepth;
	};

	struct CompressionNames
	{
		QString compression;
		QString newDnx;
		QString oldDnx;
		QString reallyOldDnx;
		bool legacyIdentifiersUsed = false;
	};

	// Unknown or ambiguous details stay unnamed. DNx retains its separately
	// verified profile and exact historical-operating-point rules.
	CompressionNames compressionNames(const CompressionFacts &facts);
}

// Descriptive names transcribed from Media Composer 26.8's installed
// SupportingFiles/CodecToolkit_Config/dfm/*.lua. The relevant module is
// named above each group. ParamExtender contains shorter UI overrides;
// those overrides deliberately do not replace these descriptions.
// Only exact identifiers are admitted: no prefix/family guesses.
constexpr auto kNames = std::array{
	// dv.lua: the coding labels distinguish DV-based and IEC-DV forms.
	NameRow{"060e2b34040101010401020202020100", "DV NTSC 25Mbps 4:1:1"},
	NameRow{"060e2b34040101010401020202020200", "DV PAL 25Mbps 4:1:1"},
	NameRow{"060e2b34040101010401020202020300", "DV NTSC 50Mbps 4:2:2"},
	NameRow{"060e2b34040101010401020202020400", "DV PAL 50Mbps 4:2:2"},
	NameRow{"060e2b34040101010401020202010100", "IEC-DV NTSC 25Mbps 4:1:1"},
	NameRow{"060e2b34040101010401020202010300", "IEC-DV NTSC 25Mbps 4:1:1"},
	NameRow{"060e2b34040101010401020202010200", "IEC-DV PAL 25Mbps 4:2:0"},
	NameRow{"060e2b34040101010401020202010400", "IEC-DV PAL 25Mbps 4:2:0"},
	NameRow{"060e2b34040101010401020202020500", "DV 1080 60i"},
	NameRow{"060e2b34040101010401020202020600", "DV 1080 50i"},
	NameRow{"060e2b34040101010401020202020700", "DV 720 60p"},
	NameRow{"060e2b34040101010401020202020800", "DV 720 50p"},

QString labelName(const QByteArray &label)
{
	static const QHash<QByteArray, QString> names = []
	{
		QHash<QByteArray, QString> result;
		result.reserve(qsizetype(kNames.size()));
		for (const auto &row : kNames)
			result.insert(QByteArray::fromHex(row.label), QString::fromLatin1(row.name));
		return result;
	}();
	return names.value(label);
}

bool isLabel(const QByteArray &label, const char *hex)
{
	return label == QByteArray::fromHex(hex);
}

QString legacyName(const CompressionFacts &facts)
{
	struct Row
	{
		const char *descriptor;
		const char *compression;
		qint64 resolution;
		const char *name;
		const char *coding1;
		const char *coding2;
	};
	// Established by Avid's supplied OMF slates, resolution resources and
	// regenerated MDB. A present unrelated label never permits fallback.
	constexpr auto rows = std::array{
		Row{"JPED", "JFIF", 78, "JFIF 15:1s", "060e2b34040101010e04020102010201", "060e2b34040101010e04020102010202"},
		Row{"JPED", "JFIF", 82, "JFIF 20:1", "060e2b34040101010e04020102010101", "060e2b34040101010e04020102010102"},
		Row{"JPED", "JFIF", 104, "JFIF 28:1", "060e2b34040101010e04020102010303", "060e2b34040101010e04020102010304"},
		Row{"JPED", "JFIF", 110, "JFIF 10:1m", "060e2b34040101010e04020102010401", "060e2b34040101010e04020102010402"},
		Row{"JPED", "JFIF", 112, "JFIF 8:1m", "060e2b34040101010e04020102010501", "060e2b34040101010e04020102010502"},
		Row{"CDCI", "DV/C", 140, "DV", "060e2b34040101010401020202020100", "060e2b34040101010401020202020200"},
		Row{"CDCI", "DV/C", 141, "DV", "060e2b34040101010401020202010200", ""},
		Row{"CDCI", "DV/C", 142, "DV", "060e2b34040101010401020202020300", "060e2b34040101010401020202020400"},
		Row{"CDCI", "DV/C", 143, "DV", "060e2b34040101010401020202020100", ""},
		Row{"CDCI", "DV/C", 144, "DV", "060e2b34040101010401020202010200", ""},
		Row{"CDCI", "AUNC", 151, "Avid Packed", "060e2b34040101010401020100000000", ""},
		Row{"CDCI", "MXF1", 151, "Avid Packed", "060e2b34040101010401020100000000", ""},
		Row{"CDCI", "AUNC", 152, "Avid Packed", "060e2b34040101010401020100000000", ""},
		Row{"CDCI", "MXF1", 152, "Avid Packed", "060e2b34040101010401020100000000", ""},
		Row{"MPGI", "MPG2", 160, "MPEG-2", "060e2b34040101010401020201020101", "060e2b34040101010401020201020102"},
	};
	for (const auto &row : rows)
	{
		const bool descriptor = facts.descriptorClass == QLatin1String(row.descriptor) ||
								(facts.descriptorClass == QLatin1String("CDCI") && QLatin1String(row.descriptor) == QLatin1String("JPED"));
		const bool coding = (facts.codingAbsent && facts.codingLabel.isEmpty()) ||
							isLabel(facts.codingLabel, row.coding1) || (row.coding2[0] && isLabel(facts.codingLabel, row.coding2));
		if (!descriptor || !coding || facts.legacyCompression != row.compression || facts.legacyResolution != row.resolution)
			continue;

		// ID 140/142 alone does not distinguish PAL and NTSC. Only the
		// checked legacy raster/clock combination supplies that extra name.
		if (row.resolution == 140 || row.resolution == 142)
		{
			const bool pal = facts.geometry == QPair<qint64, qint64>{720, 576} && facts.rate.sameRate({25, 1});
			const bool ntsc = facts.geometry.first == 720 &&
							  (facts.geometry.second == 480 || facts.geometry.second == 486) &&
							  (facts.rate.sameRate({30000, 1001}) || facts.rate.sameRate({2997, 100}));
			if (pal || ntsc)
				return QStringLiteral("DV %1 %2Mbps %3").arg(pal ? QLatin1String("PAL") : QLatin1String("NTSC")).arg(row.resolution == 140 ? 25 : 50).arg(row.resolution == 140 ? QLatin1String("4:1:1") : QLatin1String("4:2:2"));
		}
		if ((row.resolution == 141 || row.resolution == 144) &&
			facts.geometry == QPair<qint64, qint64>{720, 576} &&
			(facts.rate.sameRate({25, 1}) || (facts.layout == 0 && facts.rate.sameRate({24, 1}))))
			return QStringLiteral("IEC-DV PAL 25Mbps 4:2:0");
		if (row.resolution == 143 && facts.layout == 0 && facts.geometry.first == 720 &&
			(facts.geometry.second == 480 || facts.geometry.second == 486) &&
			(facts.rate.sameRate({24, 1}) || facts.rate.sameRate({24000, 1001})))
			return QStringLiteral("DV NTSC 25Mbps 4:1:1");
		if ((row.resolution == 151 || row.resolution == 152) &&
			facts.horizontal == 2 && facts.vertical == 1 && (facts.depth == 8 || facts.depth == 10))
			return QStringLiteral("1:1 YCbCr %1bit").arg(*facts.depth);
		if (row.resolution == 160 && facts.geometry.first == 720)
		{
			if (facts.geometry.second == 608 && facts.rate.sameRate({25, 1}))
				return QStringLiteral("SMPTE D-10/IMX 50Mbps 625x50I");
			if (facts.geometry.second == 512 &&
				(facts.rate.sameRate({30000, 1001}) || facts.rate.sameRate({2997, 100})))
				return QStringLiteral("SMPTE D-10/IMX 50Mbps 525x59.94I");
		}
		return QString::fromLatin1(row.name);
	}
	return {};
}

QString uncompressedName(const CompressionFacts &facts)
{
	// Generic uncompressed labels do not establish RGB, YCbCr or alpha
	// by themselves. Only already decoded component facts permit a name.
	if (facts.alphaDepth == 8 || facts.alphaDepth == 10)
		return QStringLiteral("1:1 Alpha %1bit").arg(*facts.alphaDepth);
	if ((facts.descriptorClass == QLatin1String("CDCI") ||
		 facts.descriptorClass == QLatin1String("CDCIEssenceDescriptor")) &&
		facts.horizontal == 2 && facts.vertical == 1 && (facts.depth == 8 || facts.depth == 10))
		return QStringLiteral("1:1 YCbCr %1bit").arg(*facts.depth);
	return {};
}

QString jpeg2000Name(const CompressionFacts &facts)
{
	// j2k.lua uses this one generic coding label for both SD and HD.
	// Only its checked HD raster/component/layout/clock combinations
	// permit the more specific name; the label alone supplies a family.
	if (isLabel(facts.codingLabel, "060e2b34040101070401020203010100") &&
		facts.depth == 10 && facts.horizontal == 2 && facts.vertical == 1)
	{
		constexpr auto progressiveRates = std::array{MediaRate{25, 1}, MediaRate{24, 1}, MediaRate{30000, 1001}, MediaRate{24000, 1001}};
		constexpr auto interlacedRates = std::array{MediaRate{25, 1}, MediaRate{30000, 1001}};
		constexpr auto hd720Rates = std::array{MediaRate{60000, 1001}, MediaRate{50, 1}, MediaRate{30000, 1001}, MediaRate{25, 1}, MediaRate{24000, 1001}};
		if (facts.geometry == QPair<qint64, qint64>{1920, 1080})
		{
			if (facts.layout == 0)
				for (const auto &rate : progressiveRates)
					if (facts.rate.sameRate(rate))
						return QStringLiteral("J2K HD");
			if (facts.layout == 1)
				for (const auto &rate : interlacedRates)
					if (facts.rate.sameRate(rate))
						return QStringLiteral("J2K HD");
		}
		if (facts.geometry == QPair<qint64, qint64>{1280, 720} && facts.layout == 0)
			for (const auto &rate : hd720Rates)
				if (facts.rate.sameRate(rate))
					return QStringLiteral("J2K HD");
	}
	return QStringLiteral("JPEG2000"); // j2k.lua codec_family.
}

CompressionNames compressionNames(const CompressionFacts &facts)
{
	CompressionNames result;
	for (const auto &profile : dnxProfiles)
	{
		if (!isLabel(facts.codingLabel, profile.label))
			continue;
		result.newDnx = QStringLiteral("Avid DNx %1").arg(QLatin1String(profile.level));
		result.oldDnx = QStringLiteral("DNx%1 %2").arg(profile.hr ? QLatin1String("HR") : QLatin1String("HD"), QLatin1String(profile.level));
		result.reallyOldDnx = reallyOldDnx(profile, facts.geometry, facts.rate, facts.layout, facts.depth, facts.horizontal, facts.vertical);
		result.compression = result.newDnx;
		if (!result.reallyOldDnx.isEmpty())
			result.compression += QStringLiteral(" [%1]").arg(result.reallyOldDnx);
		return result;
	}
	if (isLabel(facts.codingLabel, "060e2b340401010d0401020203070100") ||
		isLabel(facts.codingLabel, "060e2b340401010d0401020203070200"))
	{
		result.compression = QStringLiteral("Avid DNxUncompressed");
		if (!facts.bitDepth.isEmpty() && !facts.sampleFormat.isEmpty())
			result.compression += QStringLiteral(" — %1 %2").arg(facts.bitDepth, facts.sampleFormat);
		return result;
	}

	result.compression = labelName(facts.codingLabel);
	if (!result.compression.isEmpty())
		return result;

	if (isLabel(facts.codingLabel, "060e2b34040101010401020100000000") ||
		isLabel(facts.codingLabel, "060e2b34040101010e04020101010000") ||
		isLabel(facts.codingLabel, "060e2b34040101010e04020101020000") ||
		isLabel(facts.codingLabel, "060e2b34040101010e04030101030100") ||
		isLabel(facts.codingLabel, "060e2b34040101010e04030101030200"))
	{
		result.compression = uncompressedName(facts);
		if (!result.compression.isEmpty())
			return result;
	}

	// The generic J2K label is shared by SD and HD. A family name remains
	// useful when the component/raster facts do not establish a preset.
	if (isLabel(facts.codingLabel, "060e2b34040101070401020203010100") ||
		isLabel(facts.codingLabel, "060e2b340401010d040102020301020a") ||
		isLabel(facts.codingLabel, "060e2b340401010d0401020203010312") ||
		isLabel(facts.codingLabel, "060e2b34040101090401020203010104"))
	{
		result.compression = jpeg2000Name(facts);
		return result;
	}

	result.compression = legacyName(facts);
	if (!result.compression.isEmpty())
	{
		result.legacyIdentifiersUsed = true;
		return result;
	}
	if (facts.codingAbsent && facts.codingLabel.isEmpty())
	{
		if (facts.descriptorClass == QLatin1String("RGBA") && facts.legacyCompression == "NONE" && facts.alphaDepth)
		{
			result.compression = uncompressedName(facts);
			if (result.compression.isEmpty() && *facts.alphaDepth > 0)
				result.compression = QStringLiteral("Uncompressed alpha"); // Explicit NONE, not inferred from alpha alone.
			result.legacyIdentifiersUsed = !result.compression.isEmpty();
		}
		else if (facts.descriptorClass == QLatin1String("PCMA") || facts.descriptorClass == QLatin1String("WAVE"))
			result.compression = QStringLiteral("PCM");
	}
	return result;
}

// VC-3 labels identify profiles, independently of Avid's ResolutionID.
// Sources: ST 2019-1:2016 Annex C/H and Avid's 2012/2026 white papers;
// see Project Canon/dnx-codec-evidence.md.
inline constexpr DnxProfile dnxProfiles[] = {
	{"060e2b340401010a0401020271010000", "HQX", false, 1920, 1080, 0},
	{"060e2b340401010a0401020271070000", "HQX", false, 1920, 1080, 1},
	{"060e2b340401010a0401020271100000", "HQX", false, 1280, 720, 0},
	{"060e2b340401010a0401020271040000", "HQ", false, 1920, 1080, 0},
	{"060e2b340401010a0401020271090000", "HQ", false, 1920, 1080, 1},
	{"060e2b340401010a0401020271110000", "HQ", false, 1280, 720, 0},
	{"060e2b340401010a0401020271030000", "SQ", false, 1920, 1080, 0},
	{"060e2b340401010a0401020271080000", "SQ", false, 1920, 1080, 1},
	{"060e2b340401010a0401020271120000", "SQ", false, 1280, 720, 0},
	{"060e2b340401010a0401020271130000", "LB", false, 1920, 1080, 0},
	{"060e2b340401010d0401020271160000", "444", false, 1920, 1080, 0},
	{"060e2b340401010d0401020271250000", "HQX", true, 0, 0, -1},
	{"060e2b340401010d0401020271260000", "HQ", true, 0, 0, -1},
	{"060e2b340401010d0401020271270000", "SQ", true, 0, 0, -1},
	{"060e2b340401010d0401020271280000", "LB", true, 0, 0, -1},
	{"060e2b340401010d0401020271240000", "444", true, 0, 0, -1}};

struct DnxOperatingPoint
{
	int width;
	int height;
	int layout;
	MediaRate rate;
	const char *lb;
	const char *sq;
	const char *hq;
	const char *hqx;
	const char *rgb444;
};

// Resolution names from Avid DNxHD Technology (2012), pp. 9–10; not Mbps values.
// Thin-raster rows do not supply full-raster aliases. Interlaced 50/59.94
// uses frame clocks 25 and 30000/1001, respectively.
inline constexpr DnxOperatingPoint dnxOperatingPoints[] = {
	{1920, 1080, 0, {60, 1}, "90", "290", "440", "440x", ""},
	{1920, 1080, 0, {60000, 1001}, "90", "290", "440", "440x", ""},
	{1920, 1080, 0, {50, 1}, "75", "240", "365", "365x", ""},
	{1920, 1080, 1, {30000, 1001}, "", "145", "220", "220x", ""},
	{1920, 1080, 1, {25, 1}, "", "120", "185", "185x", ""},
	{1920, 1080, 0, {25, 1}, "36", "120", "185", "185x", "365x"},
	{1920, 1080, 0, {24, 1}, "36", "115", "175", "175x", "350x"},
	{1920, 1080, 0, {24000, 1001}, "36", "115", "175", "175x", "350x"},
	{1920, 1080, 0, {30000, 1001}, "45", "145", "220", "220x", "440x"},
	{1280, 720, 0, {60000, 1001}, "", "145", "220", "220x", ""},
	{1280, 720, 0, {50, 1}, "", "115", "175", "175x", ""},
	{1280, 720, 0, {30000, 1001}, "", "75", "110", "110x", ""},
	{1280, 720, 0, {25, 1}, "", "60", "90", "90x", ""},
	{1280, 720, 0, {24000, 1001}, "", "60", "90", "90x", ""}};

inline QString reallyOldDnx(const DnxProfile &profile, QPair<qint64, qint64> geometry,
							MediaRate rate, std::optional<qint64> layout, std::optional<qint64> depth,
							std::optional<qint64> horizontal, std::optional<qint64> vertical)
{
	const auto level = QLatin1String(profile.level);
	const int expectedDepth = level == QLatin1String("HQX") || level == QLatin1String("444") ? 10 : 8;
	const int expectedHorizontal = level == QLatin1String("444") ? 1 : 2;
	if (profile.hr || !layout || depth != expectedDepth || horizontal != expectedHorizontal || vertical != 1 ||
		(profile.layout >= 0 && profile.layout != *layout) ||
		(profile.width != 0 && (profile.width != geometry.first || profile.height != geometry.second)))
		return {};
	for (const auto &point : dnxOperatingPoints)
	{
		if (geometry.first != point.width || geometry.second != point.height || *layout != point.layout || !rate.sameRate(point.rate))
			continue;
		const auto *name = level == QLatin1String("LB") ? point.lb : level == QLatin1String("SQ") ? point.sq
																 : level == QLatin1String("HQ")	  ? point.hq
																 : level == QLatin1String("HQX")  ? point.hqx
																								  : point.rgb444;
		return name[0] ? QStringLiteral("DNxHD %1").arg(QLatin1String(name)) : QString{};
	}
	return {};
}

bool completeObject(const ParsedSource &source, const AvidObject &object)
{
	// A complete Bento read enumerates the owner's TOC entries. An unnamed
	// entry may conceal a checked property behind an unresolved dictionary
	// definition, so it cannot establish that property's absence.
	return source.outcome == ParsedSource::Outcome::Complete && !object.properties.isEmpty() &&
		   std::all_of(object.properties.cbegin(), object.properties.cend(), [&](const auto &property)
					   { return property.bento && !property.locator.name.isEmpty() &&
								property.locator.objectNumber == object.handle; });
}

QByteArray auidToUl(const RawProperty &property)
{
	if (property.state != PropertyReadState::Present || property.encoding.size() != 16 ||
		!property.bento || !property.bento->metadataBigEndian)
		return {};
	const auto &bytes = property.encoding;
	QByteArray result = bytes.mid(8, 8);
	// AAF's structured AUID fields precede the UL's first eight octets.
	if (*property.bento->metadataBigEndian)
		result += bytes.first(8);
	else
	{
		for (int index : {3, 2, 1, 0, 5, 4, 7, 6})
			result += bytes[index];
	}
	return result;
}

QByteArray knownDnxLabel(qint64 resolution)
{
	// The observed/registered IDs are explicit: the intervening numbers
	// are not proven codecs merely because an arithmetic label fits.
	switch (resolution)
	{
	case 1235:
	case 1237:
	case 1238:
	case 1241:
	case 1242:
	case 1243:
	case 1244:
	case 1250:
	case 1251:
	case 1252:
	case 1253:
		break;
	default:
		return {};
	}
	QByteArray label = QByteArray::fromHex("060e2b340401010a0401020271000000");
	label[13] = char(resolution - 1234);
	if (resolution == 1244)
		label[7] = 0x0d;
	return label;
}

MediaRate legacyDnxNamingRate(qint64 resolution, MediaRate recorded)
{
	// Only corroborated decimal clocks qualify for this naming lookup.
	// Keep recorded rates/durations unchanged. See Project Canon/dnx-codec-evidence.md.
	if (recorded.sameRate({2997, 100}))
	{
		switch (resolution)
		{
		case 1235:
		case 1237:
		case 1238:
		case 1241:
		case 1242:
		case 1243:
		case 1253:
			return {30000, 1001};
		}
	}
	if (recorded.sameRate({23976, 1000}))
	{
		switch (resolution)
		{
		case 1235:
		case 1237:
		case 1238:
		case 1250:
		case 1251:
		case 1252:
		case 1253:
			return {24000, 1001};
		}
	}
	return recorded;
}

AudioFacts waveFormat(const AvidObject &owner, const RawProperty &header)
{
	AudioFacts result;
	const auto fields = header.decoded.toMap();
	if (!fields.contains(QStringLiteral("wFormatTag")))
		return result;
	quint16 format = quint16(fields.value(QStringLiteral("wFormatTag")).toUInt());
	result.channelsProperty = audioField(owner, header, "nChannels");
	result.rateProperty = audioField(owner, header, "nSamplesPerSec");
	result.codecProperty = audioField(owner, header, "wFormatTag");
	result.bitsProperty = audioField(owner, header, "wBitsPerSample");
	result.channels = fields.value(QStringLiteral("nChannels")).toInt();
	const quint32 sampleRate = fields.value(QStringLiteral("nSamplesPerSec")).toUInt();
	if (sampleRate <= quint32(std::numeric_limits<qint32>::max()))
		result.sampleRate = {qint32(sampleRate), 1};
	result.blockAlign = quint16(fields.value(QStringLiteral("nBlockAlign")).toUInt());
	if (format == 0xfffe)
	{
		result.codecProperty = audioField(owner, header, "SubFormat");
		result.bitsProperty = audioField(owner, header, "wValidBitsPerSample");
		const auto guid = result.codecProperty && result.codecProperty->state == PropertyReadState::Present
							  ? result.codecProperty->encoding
							  : QByteArray{};
		if (guid == QByteArray::fromHex("0100000000001000800000aa00389b71"))
			format = 1;
		else if (guid == QByteArray::fromHex("0300000000001000800000aa00389b71"))
			format = 3;
		else
		{
			// Storage width remains recorded, but cannot stand in for
			// valid precision when this extension is not established.
			if (result.codecProperty && result.codecProperty->state == PropertyReadState::Unreadable)
				result.bitsProperty = result.codecProperty;
			return result;
		}
	}
	if (result.bitsProperty && result.bitsProperty->state == PropertyReadState::Present)
		result.bits = result.bitsProperty->decoded.toInt();
	if (format == 1)
	{
		result.codec = QStringLiteral("PCM");
		result.representation = QStringLiteral("Integer");
		result.uncompressed = true;
	}
	else if (format == 3)
	{
		result.codec = QStringLiteral("IEEE float");
		result.representation = QStringLiteral("Float");
		result.uncompressed = true;
	}
	return result;
}

AudioFacts aiffCommon(const AvidObject &owner, const RawProperty &header)
{
	AudioFacts result;
	const auto fields = header.decoded.toMap();
	if (!fields.contains(QStringLiteral("sampleSize")))
		return result;
	result.channelsProperty = audioField(owner, header, "numChannels");
	result.bitsProperty = audioField(owner, header, "sampleSize");
	result.rateProperty = audioField(owner, header, "sampleRate");
	result.framesProperty = audioField(owner, header, "numSampleFrames");
	result.codecProperty = audioField(owner, header, "compressionType");
	result.channels = fields.value(QStringLiteral("numChannels")).toInt();
	result.frames = fields.value(QStringLiteral("numSampleFrames")).toLongLong();
	result.bits = fields.value(QStringLiteral("sampleSize")).toInt();
	if (result.rateProperty)
		result.sampleRate = extendedRate(result.rateProperty->encoding);
	const auto codec = result.codecProperty && result.codecProperty->state == PropertyReadState::Present
						   ? result.codecProperty->encoding
						   : QByteArray{};
	if (!result.codecProperty || codec == "NONE" || codec == "twos" || codec == "sowt" || codec == "in24" || codec == "in32")
	{
		result.codec = QStringLiteral("PCM");
		result.representation = QStringLiteral("Integer");
		result.uncompressed = true;
	}
	else if (codec == "fl32" || codec == "FL32" || codec == "fl64" || codec == "FL64")
	{
		result.codec = QStringLiteral("IEEE float");
		result.representation = QStringLiteral("Float");
		result.uncompressed = true;
	}
	return result;
}

void audioObservations(ProjectedFile &file, const ParsedSource &source, const AvidObject &object,
					   const RawProperty &property, const AudioFacts &audio, bool duration)
{
	const auto add = [&](MediaProperty field, Property input, const QVariant &value)
	{
		if (input && (value.isValid() || input->state == PropertyReadState::Unreadable))
			observe(file, field, source, object, *input, value, EvidenceBasis::Derived,
					input->state == PropertyReadState::Unreadable ? input->interpretation
																  : QStringLiteral("Decoded recorded audio field %1; original field bytes retained. %2")
																		.arg(input->locator.name, input->interpretation));
	};
	add(MediaProperty::Channels, audio.channelsProperty, audio.channels > 0 ? QVariant(audio.channels) : QVariant{});
	add(MediaProperty::BitDepth, audio.bitsProperty, audio.bits > 0 && audio.bits <= 64 ? QVariant(QStringLiteral("%1-bit").arg(audio.bits)) : QVariant{});
	add(MediaProperty::SampleRate, audio.rateProperty, audio.sampleRate.valid() ? QVariant(rateValue(audio.sampleRate)) : QVariant{});
	if (audio.codecProperty || !audio.codec.isEmpty())
	{
		add(MediaProperty::Compression, audio.codecProperty ? audio.codecProperty : &property, audio.codec.isEmpty() ? QVariant{} : QVariant(audio.codec));
		add(MediaProperty::SampleFormat, audio.codecProperty ? audio.codecProperty : &property, audio.representation.isEmpty() ? QVariant{} : QVariant(audio.representation));
	}
	if (duration && audio.frames && *audio.frames >= 0 && audio.sampleRate.valid())
		observe(file, MediaProperty::FileDuration, source, object, audio.framesProperty ? *audio.framesProperty : property,
				durationValue({*audio.frames, audio.sampleRate, {}, MediaDuration::Source::Descriptor}), EvidenceBasis::Derived,
				property.locator.key == "COMM" ? QStringLiteral("Recorded sample-frame count and exact native sampling rate; no video clock inferred.")
											   : QStringLiteral("Sample-frame count derived from the single native data extent and recorded block alignment, using the exact native sampling rate; sound samples remain unread and no video clock is inferred."));
}

if (audio)
{
	MediaRate summaryRate;
	bool conflictingRates = false;
	for (const auto &header : descriptor.properties)
	{
		const bool waveSummary = (cls == QLatin1String("WAVD") || cls == QLatin1String("WAVE")) &&
								 header.locator.name == QLatin1String("OMFI:WAVD:Summary.fmt ");
		const bool aiffSummary = cls == QLatin1String("AIFD") && header.locator.name == QLatin1String("OMFI:AIFD:Summary.COMM");
		if (!waveSummary && !aiffSummary)
			continue;
		const auto facts = waveSummary ? waveFormat(descriptor, header) : aiffCommon(descriptor, header);
		// Compression is the actual encoding; WAVE/AIFF is retained as the
		// descriptor/container fact, not substituted for compression.
		audioObservations(file, m_source, descriptor, header, facts, false);
		if (facts.sampleRate.valid())
		{
			if (summaryRate.valid() && (summaryRate.numerator != facts.sampleRate.numerator || summaryRate.denominator != facts.sampleRate.denominator))
				conflictingRates = true;
			else
				summaryRate = facts.sampleRate;
		}
	}
	if (!unitsRate.valid() && !conflictingRates)
		unitsRate = summaryRate;
	for (const auto *channels : properties(descriptor, {"OMFI:MDAU:NumChannels"}))
		if (const auto value = integer(channels); value && *value > 0)
			observe(file, MediaProperty::Channels, m_source, descriptor, *channels, *value);
}

const auto *coding = uniqueRaw(descriptor, {"OMFI:DIDD:EssenceCompression"});
const bool codingAbsent = properties(descriptor, {"OMFI:DIDD:EssenceCompression"}).isEmpty();
const auto layout = integer(unique(descriptor, {"OMFI:DIDD:FrameLayout"}));
const bool omf1 = !properties(descriptor, {"OMFI:ObjID"}).isEmpty();
const auto *storedWidthProperty = unique(descriptor, {"OMFI:DIDD:StoredWidth"});
const auto storedWidth = integer(storedWidthProperty);
const auto storedHeight = integer(unique(descriptor, {"OMFI:DIDD:StoredHeight"}));
qint64 frameHeight = storedHeight.value_or(0);
if (layout && (*layout == 1 || (omf1 && *layout == 3)))
	frameHeight = frameHeight > 0 && frameHeight <= std::numeric_limits<qint64>::max() / 2 ? frameHeight * 2 : 0;
QByteArray label = coding ? auidToUl(*coding) : QByteArray{};
const auto *resolutionId = unique(descriptor, {"OMFI:DIDD:DIDResolutionID"});
const auto resolution = integer(resolutionId);
Property codecProperty = coding;
if (label.isEmpty() && codingAbsent && resolution)
{
	label = knownDnxLabel(*resolution);
	codecProperty = resolutionId;
}
if (!label.isEmpty())
	observe(file, MediaProperty::CompressionLabel, m_source, descriptor, *codecProperty, label, EvidenceBasis::Derived,
			coding ? QStringLiteral("Recorded structured AUID converted to its UL octet order.") : QStringLiteral("Verified Avid DNx resolution-ID mapping; not a recorded compression UL."));

Detail::CompressionFacts facts;
facts.codingLabel = label;
facts.descriptorClass = cls;
facts.codingAbsent = codingAbsent && complete;
facts.geometry = {storedWidth.value_or(0), frameHeight};
const auto namingRate = resolution && label == knownDnxLabel(*resolution)
							? legacyDnxNamingRate(*resolution, unitsRate)
							: unitsRate;
facts.rate = namingRate;
facts.layout = layout;
facts.depth = integer(unique(descriptor, {"OMFI:CDCI:ComponentWidth"}));
facts.horizontal = integer(unique(descriptor, {"OMFI:CDCI:HorizontalSubsampling"}));
facts.vertical = integer(unique(descriptor, {"OMFI:CDCI:VerticalSubsampling"}));
const auto *compression = uniqueRaw(descriptor, {"OMFI:DIDD:Compression"});
// Only typed descriptor identifiers enter the legacy name table. An
// unknown or conflicting coding property is not evidence of absence.
if (resolutionId && compression && resolutionId->bento && compression->bento &&
	named(resolutionId->bento->typeName, {"omfi:Long", "omfi:Int32", "omfi:UInt32"}) &&
	resolutionId->encoding.size() == 4 && compression->bento->typeName == QLatin1String("omfi:String") &&
	(compression->encoding.size() == 4 ||
	 (compression->encoding.size() == 5 && compression->encoding.back() == '\0')))
{
	facts.legacyResolution = resolution;
	facts.legacyCompression = compression->encoding.first(4);
}

const auto saveCodec = [&]
{
	const auto descriptorValue = [&](MediaProperty field)
	{
		QString selected;
		for (const auto &value : file.evidence.observations(field))
			if (value.objectIdentity == QStringLiteral("object:%1").arg(descriptor.handle) && value.readState == PropertyReadState::Present)
			{
				if (!selected.isEmpty() && selected != value.value.toString())
					return QString{};
				selected = value.value.toString();
			}
		return selected;
	};
	facts.bitDepth = descriptorValue(MediaProperty::BitDepth);
	facts.sampleFormat = descriptorValue(MediaProperty::SampleFormat);
	const auto names = Detail::compressionNames(facts);
	if (!names.newDnx.isEmpty() && codecProperty)
		observe(file, MediaProperty::NewDnx, m_source, descriptor, *codecProperty, names.newDnx, EvidenceBasis::Derived,
				QStringLiteral("Verified coding profile mapped to Avid's unified DNx branding."));
	if (!names.oldDnx.isEmpty() && codecProperty)
		observe(file, MediaProperty::OldDnx, m_source, descriptor, *codecProperty, names.oldDnx,
				EvidenceBasis::Derived, QStringLiteral("Historical HD/HR profile identity; not inferred from image dimensions."));
	if (!names.reallyOldDnx.isEmpty() && codecProperty)
		observe(file, MediaProperty::ReallyOldDnx, m_source, descriptor, *codecProperty, names.reallyOldDnx, EvidenceBasis::Derived,
				!namingRate.sameRate(unitsRate)
					? QStringLiteral("Verified legacy OMF/MDB name-table clock spelling for resolution ID %1: recorded %2/%3, naming operating point %4/%5. Matching MDB/MXF identities or Avid's supplied OMF slate corroborate this exact profile/clock pair; raster, layout, depth and sampling must also match Avid's 2012 white paper pp. 9–10. Recorded Frame Rate and Duration are unchanged.")
						  .arg(*resolution)
						  .arg(unitsRate.numerator)
						  .arg(unitsRate.denominator)
						  .arg(namingRate.numerator)
						  .arg(namingRate.denominator)
					: QStringLiteral("Exact profile, stored raster, frame layout, depth, sampling and rational rate match Avid's 2012 white paper pp. 9–10."));
	const auto *anchor = names.legacyIdentifiersUsed ? compression : codecProperty;
	if (!anchor && (cls == QLatin1String("PCMA") || cls == QLatin1String("WAVE")))
		anchor = classProperty;
	if (!names.compression.isEmpty() && anchor)
		observe(file, MediaProperty::Compression, m_source, descriptor, *anchor, names.compression, EvidenceBasis::Derived,
				names.legacyIdentifiersUsed
					? QStringLiteral("Typed %1 descriptor Compression '%2' and applicable DIDResolutionID/descriptor facts match the shared verified Avid name catalogue%3; original properties retained.")
						  .arg(cls, QString::fromLatin1(compression->encoding.first(4)), codingAbsent ? QStringLiteral("; EssenceCompression is absent") : QStringLiteral(" and its exact compatible recorded EssenceCompression label"))
					: QStringLiteral("Established descriptor coding and shared verified Avid compression-name catalogue; original identifiers retained."));
};

	const auto *pixels = uniqueRaw(descriptor, {"OMFI:RGBA:PixelLayout"});
	const auto *depths = uniqueRaw(descriptor, {"OMFI:RGBA:PixelStructure"});
	if (cls == QLatin1String("RGBA") && pixels)
	{
		observe(file, MediaProperty::PixelLayout, m_source, descriptor, *pixels, pixels->encoding);
		const auto terminator = pixels->encoding.indexOf('\0');
		const auto count = terminator < 0 ? pixels->encoding.size() : terminator;
		bool known = count > 0 && count <= 8;
		QSet<char> seen;
		for (qsizetype index = 0; index < count; ++index)
		{
			const char code = pixels->encoding[index];
			if (!QByteArray("ABFGPR0").contains(code) || (code != '0' && seen.contains(code)))
				known = false;
			seen.insert(code);
		}
		if (known)
		{
			// Require explicit no-compression and a sole alpha component;
			// missing coding alone cannot establish uncompressed alpha.
			const auto oneValue = [](const QByteArray &bytes, char expected)
			{
				return bytes == QByteArray(1, expected) ||
					   bytes == QByteArray(1, expected) + '\0';
			};
			if (codingAbsent && complete &&
				compression && (compression->encoding == "NONE" || compression->encoding == QByteArray("NONE\0", 5)) &&
				oneValue(pixels->encoding, 'A') && depths && !depths->encoding.isEmpty() &&
				quint8(depths->encoding.front()) > 0 && quint8(depths->encoding.front()) <= 64 &&
				oneValue(depths->encoding, depths->encoding.front()))
			{
				facts.legacyCompression = QByteArray("NONE");
				facts.alphaDepth = quint8(depths->encoding.front());
			}
			observe(file, MediaProperty::Alpha, m_source, descriptor, *pixels, seen.contains('A'), EvidenceBasis::Derived,
					QStringLiteral("Explicit complete RGBA component list; transparency polarity alone is not presence evidence."));
			if (depths && depths->encoding.size() >= count)
			{
				QSet<int> widths;
				for (qsizetype index = 0; index < count; ++index)
					if (pixels->encoding[index] != 'F' && pixels->encoding[index] != '0')
						widths.insert(quint8(depths->encoding[index]));
				if (widths.size() == 1 && *widths.cbegin() > 0 && *widths.cbegin() <= 64)
					observe(file, MediaProperty::BitDepth, m_source, descriptor, *depths,
							QStringLiteral("%1-bit").arg(*widths.cbegin()), EvidenceBasis::Derived,
							QStringLiteral("All described non-fill RGBA components have this recorded width; component arrays remain separate."));
			}
		}
	}
	saveCodec();
}

RawProperty audioSlice(const RawProperty &parent, const QString &suffix, qsizetype offset, qsizetype length)
{
    RawProperty result;
    result.locator.name = parent.locator.name + QLatin1Char('.') + suffix;
    result.locator.objectNumber = parent.locator.objectNumber;
    result.bento = parent.bento;
    const qsizetype available = std::max(qsizetype(0), parent.encoding.size() - offset);
    const qsizetype retained = std::min(length, available);
    result.encoding = parent.encoding.mid(offset, retained);
    result.state = retained == length ? PropertyReadState::Present : PropertyReadState::Unreadable;
    // Bento can split one value across several physical ranges. Map the
    // field's logical bytes through them instead of assuming contiguity.
    qint64 skip = std::min(offset, parent.encoding.size());
    qint64 remaining = retained;
    for (const auto &range : parent.locator.ranges)
    {
        if (skip > range.length || (skip == range.length && remaining > 0))
        {
            skip -= range.length;
            continue;
        }
        const qint64 count = std::min(remaining, range.length - skip);
        result.locator.ranges.append({range.offset + skip, count});
        remaining -= count;
        skip = 0;
        if (remaining == 0)
            break;
    }
    return result;
}

class AudioFields
{
public:
    explicit AudioFields(const RawProperty &property) : m_property(property) {}

    void add(const QString &name, qsizetype offset, qsizetype length, const QVariant &value = {})
    {
        auto field = audioSlice(m_property, name, offset, length);
        if (field.state == PropertyReadState::Present)
        {
            field.decoded = value;
            if (value.isValid())
                result.values.insert(name, value);
        }
        else
            fail(field, QStringLiteral("Recorded %1 is truncated.").arg(name));
        result.fields.append(std::move(field));
    }

    void fail(RawProperty &field, const QString &reason)
    {
        field.state = PropertyReadState::Unreadable;
        field.interpretation = reason;
        result.diagnostics.append(reason);

AudioFormatResult decodeWaveFormat(const RawProperty &property)
{
    AudioFields fields(property);
    const auto &bytes = property.encoding;
    if (bytes.size() < 16)
    {
        fields.add(QStringLiteral("FixedFields"), 0, 16);
        return std::move(fields.result);
    }
    const quint16 tag = word(bytes, 0, false);
    fields.add(QStringLiteral("wFormatTag"), 0, 2, tag);
    fields.add(QStringLiteral("nChannels"), 2, 2, word(bytes, 2, false));
    fields.add(QStringLiteral("nSamplesPerSec"), 4, 4, dword(bytes, 4, false));
    fields.add(QStringLiteral("nAvgBytesPerSec"), 8, 4, dword(bytes, 8, false));
    fields.add(QStringLiteral("nBlockAlign"), 12, 2, word(bytes, 12, false));
    fields.add(QStringLiteral("wBitsPerSample"), 14, 2, word(bytes, 14, false));
    fields.result.fields.last().interpretation = QStringLiteral("Recorded sample storage width; an extensible format can record a different valid precision.");
    if (tag == 1 && bytes.size() == 16)
        return std::move(fields.result);
    fields.add(QStringLiteral("cbSize"), 16, 2, bytes.size() >= 18 ? QVariant(word(bytes, 16, false)) : QVariant{});
    if (bytes.size() < 18)
        return std::move(fields.result);
    const quint16 extra = word(bytes, 16, false);
    if (extra > bytes.size() - 18)
        fields.fail(fields.result.fields.last(), QStringLiteral("WAVEFORMATEX cbSize extends beyond its fmt chunk."));
    if (tag != 0xfffe)
        return std::move(fields.result);

    fields.add(QStringLiteral("Samples"), 18, 2, bytes.size() >= 20 ? QVariant(word(bytes, 18, false)) : QVariant{});
    fields.add(QStringLiteral("dwChannelMask"), 20, 4, bytes.size() >= 24 ? QVariant(dword(bytes, 20, false)) : QVariant{});
    fields.result.fields.last().interpretation += QStringLiteral(" Channel mask describes speaker assignments, not free-text channel names.");
    fields.add(QStringLiteral("SubFormat"), 24, 16, bytes.size() >= 40 ? QVariant(bytes.mid(24, 16)) : QVariant{});
    if (extra < 22)
        fields.fail(fields.result.fields.last(), QStringLiteral("WAVE_FORMAT_EXTENSIBLE requires 22 declared extension bytes."));
    const auto &subformat = fields.result.fields.last();
    const auto pcm = QByteArray::fromHex("0100000000001000800000aa00389b71");
    const auto floatingPoint = QByteArray::fromHex("0300000000001000800000aa00389b71");
    if (subformat.state == PropertyReadState::Present && (subformat.encoding == pcm || subformat.encoding == floatingPoint))
    {
        const quint16 precision = word(bytes, 18, false);
        fields.add(QStringLiteral("wValidBitsPerSample"), 18, 2, precision);
        fields.result.fields.last().interpretation = QStringLiteral("The Samples union means valid sample precision for this recorded PCM/IEEE-float SubFormat.");
        if (precision == 0)
            fields.result.fields.last().interpretation += QStringLiteral(" The recorded zero does not establish a usable precision.");
        if (precision > word(bytes, 14, false))
            fields.fail(fields.result.fields.last(), QStringLiteral("Recorded valid precision exceeds the recorded sample storage width; neither number is changed."));
    }
    return std::move(fields.result);
}

AudioFormatResult decodeAiffCommon(const RawProperty &property, bool compressed)
{
    AudioFields fields(property);
    const auto &bytes = property.encoding;
    if (bytes.size() < 18)
    {
        fields.add(QStringLiteral("FixedFields"), 0, 18);
        return std::move(fields.result);
    }
    fields.add(QStringLiteral("numChannels"), 0, 2, qint16(word(bytes, 0, true)));
    fields.add(QStringLiteral("numSampleFrames"), 2, 4, dword(bytes, 2, true));
    fields.add(QStringLiteral("sampleSize"), 6, 2, qint16(word(bytes, 6, true)));
    const quint16 signExponent = word(bytes, 8, true);
    const quint16 exponent = signExponent & 0x7fff;
    const quint64 mantissa = qFromBigEndian<quint64>(bytes.constData() + 10);
    fields.add(QStringLiteral("sampleRateSignExponent"), 8, 2, signExponent);
    fields.add(QStringLiteral("sampleRateSignificand"), 10, 8, QVariant::fromValue(mantissa));
    QVariant sampleRate;
    if (exponent != 0x7fff)
    {
        double approximation = std::ldexp(double(mantissa), (exponent == 0 ? 1 : exponent) - 16383 - 63);
        if (signExponent & 0x8000)
            approximation = -approximation;
        if (std::isfinite(approximation))
            sampleRate = approximation;
    }
    fields.add(QStringLiteral("sampleRate"), 8, 10, sampleRate);
    fields.result.fields.last().interpretation = QStringLiteral("Original 80-bit sampling-rate bytes retained; the double approximation may be rounded and does not describe the sound samples' numeric format.");
    if (!compressed)
        return std::move(fields.result);
    fields.add(QStringLiteral("compressionType"), 18, 4, bytes.size() >= 22 ? QVariant(bytes.mid(18, 4)) : QVariant{});
    fields.add(QStringLiteral("compressionNameLength"), 22, 1, bytes.size() >= 23 ? QVariant(quint8(bytes[22])) : QVariant{});
    if (bytes.size() < 23)
    {
        auto name = audioSlice(property, QStringLiteral("compressionName"), 23, 0);
        fields.fail(name, QStringLiteral("AIFF-C compression-name length is missing; independently recorded base fields and compression type remain usable."));
        fields.result.fields.append(std::move(name));
        return std::move(fields.result);
    }
    const qsizetype length = quint8(bytes[22]);
    fields.add(QStringLiteral("compressionName"), 23, length);
    auto &name = fields.result.fields.last();
    if (name.state == PropertyReadState::Present)
    {
        fields.result.values.insert(QStringLiteral("compressionNameBytes"), name.encoding);
        const bool ascii = std::all_of(name.encoding.cbegin(), name.encoding.cend(), [](char c)
                                       { return static_cast<unsigned char>(c) < 128; });
        name.textEncoding = ascii ? TextEncoding::Ascii : TextEncoding::Unknown;
        if (ascii)
        {
            name.decoded = QString::fromLatin1(name.encoding);
            name.textEncodingBasis = EvidenceBasis::Derived;
            fields.result.values.insert(QStringLiteral("compressionName"), name.decoded);
        }
        name.interpretation = QStringLiteral("AIFF-C compressionName is a counted Pascal string, potentially localized. ASCII is recognized from its bytes; non-ASCII encoding is not assumed to be MacRoman or UTF-8.");
    }
    return std::move(fields.result);

QVector<RawProperty> decodeAudioSummary(const RawProperty &summary)
{
    QVector<RawProperty> result;
    const auto &bytes = summary.encoding;
    if (summary.state != PropertyReadState::Present || !summary.bytesRetained || !summary.bento ||
        (summary.bento->typeName != QLatin1String("omfi:DataValue") && summary.bento->typeName != QLatin1String("omfi:VarLenBytes")))
        return result;
    if (bytes.size() < 12)
    {
        auto header = audioSlice(summary, QStringLiteral("ContainerHeader"), 0, 12);
        header.interpretation = QStringLiteral("Audio Summary container header is truncated; no format fields inferred.");
        result.append(std::move(header));
        return result;
    }
    const bool wave = summary.locator.name == QLatin1String("OMFI:WAVD:Summary") && bytes.first(4) == "RIFF" && bytes.mid(8, 4) == "WAVE";
    const bool aiff = summary.locator.name == QLatin1String("OMFI:AIFD:Summary") && bytes.first(4) == "FORM" && (bytes.mid(8, 4) == "AIFF" || bytes.mid(8, 4) == "AIFC");
    if (!wave && !aiff)
    {
        auto header = audioSlice(summary, QStringLiteral("ContainerHeader"), 0, 12);
        header.interpretation = QStringLiteral("Audio Summary bytes retained, but this container signature has no supported interpretation.");
        result.append(std::move(header));
        return result;
    }
    // A Summary is a header copy, not a recording. Its sample chunk may
    // describe sound bytes deliberately omitted from this property.
    for (qsizetype offset = 12; offset <= bytes.size() - 8;)
    {
        const auto key = bytes.mid(offset, 4);
        const quint32 length = dword(bytes, offset + 4, aiff);
        if (key == "data" || key == "SSND")
            break;
        if (length > quint64(bytes.size() - offset - 8))
        {
            auto chunk = audioSlice(summary, chunkName(key), offset + 8, length);
            chunk.state = PropertyReadState::Unreadable;
            chunk.interpretation = QStringLiteral("Copied metadata chunk extends beyond its Summary; omitted sample data is not required here.");
            result.append(std::move(chunk));
            break;
        }
        if ((wave && key == "fmt ") || (aiff && key == "COMM"))
        {
            auto chunk = audioSlice(summary, chunkName(key), offset + 8, length);
            chunk.locator.key = key;
            auto decoded = wave ? decodeWaveFormat(chunk) : decodeAiffCommon(chunk, bytes.mid(8, 4) == "AIFC");
            chunk.decoded = std::move(decoded.values);
            chunk.interpretation = QStringLiteral("Decoded audio fields copied inside this OMF descriptor Summary; this is not the media file's native header.");
            if (!decoded.diagnostics.isEmpty())
                chunk.interpretation += QLatin1Char(' ') + decoded.diagnostics.join(QLatin1Char(' '));
            result.append(std::move(chunk));
            result += decoded.fields;
        }
        offset += 8 + qsizetype(length) + (length & 1);
    }
    return result;

