MediaEngine::ParsedSource read(QByteArray bytes, bool database = true)
{
	QBuffer input(&bytes);
	input.open(QIODevice::ReadOnly);
	MediaEngine::Cancellation cancellation;
	return database ? MediaEngine::MdbReader{}.read(input, {{}, cancellation}) : MediaEngine::OmfReader{}.read(input, {{}, cancellation});
}

MediaEngine::Projection project(const MediaEngine::ParsedSource &source)
{
	MediaEngine::Cancellation cancellation;
	return source.snapshot && source.snapshot->source == MetadataSource::Mdb
		? MediaEngine::projectMdb(source, cancellation) : MediaEngine::projectOmf(source, cancellation);
}

